input.command:
$f = Get-ChildItem -LiteralPath . -Recurse -File -Force | Where-Object {
  $_.FullName -notmatch '\\(node_modules|dist|\.git|\.router-history|\.vitest|\.kilocode|\.opencode|\.tmp-test-router)\b' -and
  $_.FullName -notmatch '\\data\\history\.json$' -and
  $_.FullName -notmatch '\\repomix-output\.(txt|xml)$' -and
  $_.FullName -notmatch '\\repo-bundle\.md$'
}
$f | Sort-Object Length -Descending | Select-Object -First 10 | ForEach-Object {
  '{0,12:N0}  {1}' -f $_.Length, $_.FullName.Substring((Get-Location).Path.Length+1)
}
"----"
"Salida repomix:"
$out = Get-Item -LiteralPath repomix-output.txt
'{0,12:N0}  {1}' -f $out.Length, $out.Name
